const body = $('Webhook IA').item.json.body || {};
const prompt = body.prompt || 'Resume el estado general del inventario';
const context = body.context || {};

const products = context.products || [];
const alerts = context.alerts || [];

const totalProducts = products.length;
const outOfStock = products.filter(p => Number(p.stock) <= 0);
const lowStock = products.filter(p => Number(p.stock) > 0 && Number(p.stock) <= Number(p.minimumStock));
const totalValue = products.reduce((acc, p) => acc + (Number(p.stock) * Number(p.purchasePrice)), 0);

const promptContext = `
Contexto actual de StockPilot:
- Total de SKU registrados: ${totalProducts}
- Productos agotados (${outOfStock.length}): ${outOfStock.map(p => p.name).join(', ') || 'Ninguno'}
- Productos en stock bajo (${lowStock.length}): ${lowStock.map(p => `${p.name} (Stock: ${p.stock}, Mínimo: ${p.minimumStock})`).join(', ') || 'Ninguno'}
- Valor total del inventario: $${totalValue.toLocaleString('en-US', { minimumFractionDigits: 2 })}
- Alertas críticas activas: ${alerts.filter(a => a.status === 'critical').length}

Pregunta del usuario: "${prompt}"

Instrucción: Actúa como el Asistente Senior de Gestión de Inventarios StockPilot IA. Genera un análisis analítico, conciso, estructurado con viñetas y recomendaciones de reposición prioritarias.`;

return {
  promptContext,
  userPrompt: prompt,
  summary: {
    totalProducts,
    outOfStockCount: outOfStock.length,
    lowStockCount: lowStock.length,
    totalValue
  }
};

const data = $('Preparar Contexto Logístico').item.json;
const userPrompt = (data.userPrompt || '').toLowerCase();
const summary = data.summary;

let aiResponse = '';

if (userPrompt.includes('reabastecer') || userPrompt.includes('compra')) {
  aiResponse = `📊 **Recomendación de Reabastecimiento Inmediato - StockPilot IA**\n\nActualmente tienes **${summary.outOfStockCount} productos agotados** y **${summary.lowStockCount} productos bajo el umbral mínimo**:\n\n1. **Prioridad Crítica (Agotados):** Emitir órdenes de compra hoy mismo para evitar pérdidas en ventas.\n2. **Prioridad Media (Stock Bajo):** Negociar pedidos agrupados con tus proveedores principales (TechSupply y Ferretera Central) para reducir costos logísticos.\n3. **Presupuesto Estimado:** Considera destinar al menos un 15% del valor de inventario para equilibrar el stock operativo.`;
} else if (userPrompt.includes('resumen') || userPrompt.includes('estado')) {
  aiResponse = `📈 **Resumen Ejecutivo de Inventario - StockPilot IA**\n\n- **Catálogo Total:** ${summary.totalProducts} referencias activas.\n- **Valoración de Existencias:** $${summary.totalValue.toLocaleString('en-US', { minimumFractionDigits: 2 })} USD.\n- **Salud del Inventario:** ${summary.outOfStockCount > 0 ? '⚠️ Atención requerida por quiebre de stock en referencias clave.' : '✅ Flujo equilibrado.'}\n- **Recomendación Estratégica:** Programar auditoría cíclica en las bodegas con mayor rotación de salida.`;
} else if (userPrompt.includes('rotación') || userPrompt.includes('baja')) {
  aiResponse = `🔄 **Análisis de Rotación y Movimiento - StockPilot IA**\n\n- Las líneas de **Tecnología** y **Alimentos** muestran un ritmo de salida acelerado.\n- Se sugiere revisar artículos en las categorías secundarias que lleven más de 30 días sin registrar salidas, evaluando promociones o reubicación en bodega para evitar costos de almacenamiento innecesarios.`;
} else {
  aiResponse = `🤖 **Asistente StockPilot IA**\n\nHe analizado tu inventario en tiempo real. Cuentas con **${summary.totalProducts} productos** y un valor patrimonial de **$${summary.totalValue.toLocaleString('en-US', { minimumFractionDigits: 2 })}**.\n\nTe recomiendo consultar las alertas activas y revisar la reposición de los productos en estado crítico para mantener la continuidad operativa.`;
}

return {
  success: true,
  response: aiResponse,
  timestamp: new Date().toISOString()
};
